fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // Calculate the difference
    let diff = a.wrapping_sub(b);
    
    // Check if diff is strictly between -tol and tol
    // Since tol is strictly positive, we can use simple comparisons
    diff > -tol && diff < tol
}

fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    // The problem guarantees arrays have equal, non-zero length
    // so we can safely iterate through both arrays
    a.iter()
        .zip(b.iter())
        .map(|(&x, &y)| is_close_i8(x, y, tol))
        .collect()
}